"""Original sepsis chapter using Sepsis-3 and the 2026 SSC update."""
from qbank_authoring import question,ref,finalize
SS=ref('Surviving Sepsis Campaign: Adult Sepsis and Septic Shock Guidelines, 2026','https://sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026')
S3=ref('Sepsis-3: Third International Consensus Definitions','https://jamanetwork.com/journals/jama/fullarticle/2492881')
CO=ref('SCCM Focused Update: Corticosteroids in Sepsis, ARDS and CAP, 2024','https://www.sccm.org/clinical-resources/guidelines/guidelines/use-of-corticosteroids-in-sepsis-ards-cap')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which definition best describes sepsis under Sepsis-3?', 'Life-threatening organ dysfunction caused by a dysregulated host response to infection',[
 ('Any infection accompanied by fever','Fever alone does not establish organ dysfunction.'),('A positive blood culture regardless of clinical status','Bacteremia and sepsis are distinct concepts.'),('Two SIRS criteria even when infection is absent','SIRS is nonspecific and is not the Sepsis-3 definition.')],
 'Sepsis links infection to acute organ dysfunction', '**The host response can injure organs beyond the original infectious site.**',['Culture negativity does not exclude sepsis.','Baseline organ dysfunction must be considered when assessing an acute change.'], '**Recognize organ injury early while evaluating the source.**',['Altered mentation, hypoxemia, oliguria and hypotension can be clues.','Treatment must not wait for every diagnostic result.'],[['Infection alone','Not necessarily sepsis'],['Sepsis','Infection-associated life-threatening organ dysfunction'],['Bacteremia','Organisms in blood, with variable clinical impact']],[S3])
q('What acute SOFA change is used operationally to represent organ dysfunction in Sepsis-3 when infection is suspected?', 'An increase of at least two points',[
 ('Any heart rate above 90/min','That is a SIRS component, not the SOFA change.'),('A positive urine culture alone','It does not quantify organ dysfunction.'),('An isolated fever above 38°C','Temperature is not itself the relevant SOFA criterion.')],
 'SOFA operationalizes a change in organ function', '**Interpret the increase relative to the patient’s baseline.**',['The score includes several organ systems.','Not every abnormal value is newly caused by infection.'], '**A score supports clinical assessment rather than delaying treatment.**',['Screening and diagnosis are separate functions.','Consider alternative causes of organ injury in parallel.'],[['Operational change','SOFA increase ≥2'],['Baseline','Account for chronic dysfunction'],['Clinical action','Do not wait for a complete score in an emergency']],[S3])
q('After adequate volume assessment, an infected patient requires vasopressors to maintain MAP 65 mmHg and has lactate 3.5 mmol/L. Which Sepsis-3 category is met?', 'Septic shock',[
 ('Bacteremia without sepsis','The circulatory and metabolic abnormalities indicate a much more severe syndrome.'),('Uncomplicated infection because MAP is now 65','The need for vasopressor support is part of the definition.'),('SIRS alone','The patient has shock-associated organ dysfunction.')],
 'A supported blood pressure does not mean shock has resolved', '**Septic shock combines vasopressor-dependent hypotension with lactate above 2 mmol/L despite adequate resuscitation.**',['The definition identifies a high-risk sepsis subset.','Lactate is interpreted within the clinical and resuscitation context.'], '**Continue simultaneous infection treatment and hemodynamic support.**',['Assess the source and perfusion repeatedly.','Consider other shock mechanisms if the clinical picture is mixed.'],[['Vasopressor','Needed for MAP ≥65'],['Lactate','Above 2 after adequate volume resuscitation'],['Category','Septic shock']],[S3],style='clinical_scenario')
q('Which three bedside findings compose qSOFA?', 'Respiratory rate ≥22/min, systolic BP ≤100 mmHg and altered mentation',[
 ('Fever, tachycardia and leukocytosis','These resemble SIRS features.'),('Lactate, bilirubin and creatinine','These are not the three qSOFA variables.'),('Platelet count, INR and urine output','These are not the qSOFA components.')],
 'qSOFA is a simple prognostic prompt rather than a complete diagnostic definition', '**Its variables flag physiological deterioration.**',['A low score does not reliably exclude sepsis.','It does not identify the infectious source.'], '**Use a sensitive screening process and clinical judgment.**',['The 2026 SSC favors other established tools over qSOFA alone for screening.','Escalate care for a concerning clinical trajectory regardless of the score.'],[['Respiration','≥22/min'],['Blood pressure','Systolic ≤100'],['Neurology','Altered mentation']],[S3,SS])
q('Which statement reflects the 2026 SSC recommendation on hospital sepsis screening?', 'Use established tools such as NEWS/NEWS2, MEWS or SIRS rather than qSOFA as the sole screening tool',[
 ('qSOFA alone should be the only hospital screening method','Its limited sensitivity makes this inappropriate.'),('No structured screening is appropriate for acutely ill high-risk patients','SSC supports systematic screening within improvement programs.'),('A single normal biomarker definitively excludes sepsis','Sepsis is a clinical diagnosis.')],
 'A screening tool must detect deterioration early enough to act', '**qSOFA can miss patients who need urgent evaluation.**',['Different systems use different validated screening tools.','A positive screen triggers assessment rather than automatically proving sepsis.'], '**Connect screening to an actionable clinical response.**',['Review infection likelihood, organ dysfunction and immediate threats.','A multidisciplinary huddle can expedite assessment and treatment.'],[['Screen','Identify possible deterioration'],['Clinical assessment','Establish likely cause and urgency'],['Action','Timely treatment and reassessment']],[SS])
q('A patient has suspected septic shock. Which antibiotic-timing strategy is recommended by the 2026 SSC?', 'Administer appropriate antimicrobials immediately, ideally within one hour of recognition',[
 ('Wait for final blood-culture susceptibility before starting','Shock requires immediate empirical treatment.'),('Use a three-hour observation period routinely for all shock cases','That is not the recommended shock pathway.'),('Start only if procalcitonin is above a fixed cutoff','The biomarker should not gate treatment in this emergency.')],
 'Shock changes the acceptable delay in treating likely infection', '**Empirical therapy should cover the plausible source and relevant resistance risk.**',['Obtain cultures promptly if this does not create harmful delay.','Use correct dosing and account for allergy and organ function.'], '**Reassess and narrow therapy when evidence arrives.**',['Immediate broad treatment and later stewardship are compatible.','Source control must proceed in parallel when required.'],[['Shock','Immediate therapy, ideally within one hour'],['Before treatment','Cultures when promptly feasible'],['Later','Reassess and de-escalate']],[SS],style='clinical_scenario')
q('An adult has possible sepsis without shock and genuine uncertainty about infection. What does the 2026 SSC suggest?', 'Perform a rapid time-limited investigation and, if concern persists, give antimicrobials within three hours of first suspicion',[
 ('Observe without reassessment for 24 hours','This risks harmful delay.'),('Treat every low-probability noninfectious illness indefinitely','The likelihood of infection must be evaluated.'),('Wait for a positive culture in all cases','Cultures may be negative or too slow to guide the initial decision.')],
 'Diagnostic uncertainty without shock permits a brief structured assessment', '**This pathway differs from probable/definite sepsis or shock.**',['Examine for infection and alternative acute diagnoses.','Assess organ dysfunction and the clinical trajectory.'], '**Act within the time-limited pathway if infection remains a concern.**',['If infection is unlikely and shock absent, close monitoring with deferred antibiotics can be appropriate.','Escalate immediately if instability develops.'],[['Possible, no shock','Rapid investigation'],['Persistent concern','Antibiotics within three hours'],['Low likelihood','Close observation may support deferral']],[SS],style='clinical_scenario')
q('A patient has probable sepsis with acute organ dysfunction but no shock. Under the 2026 SSC, which timing is recommended?', 'Immediate antimicrobials, ideally within one hour of recognition',[
 ('Automatically wait three hours even though infection is probable','The three-hour pathway concerns possible sepsis with uncertainty and no shock.'),('Wait until hypotension develops','Organ dysfunction already makes the syndrome urgent.'),('Require bacteremia before treatment','Blood-culture positivity is not required.')],
 'Probability of infection as well as shock status guides timing', '**Probable or definite sepsis warrants prompt antimicrobial treatment.**',['Normotension does not imply absence of serious organ injury.','Use the source and resistance history to select a suitable regimen.'], '**Continue diagnostic refinement after treatment starts.**',['Collect suitable specimens promptly.','Reconsider or stop therapy when an alternative cause is demonstrated.'],[['Probable/definite sepsis','Immediate treatment'],['Possible sepsis, no shock','Brief rapid investigation pathway'],['Shock','Immediate treatment regardless of initial diagnostic uncertainty']],[SS])
q('A patient with septic shock has an obstructed infected collecting system. Which principle best addresses the underlying infection?', 'Urgent decompression/source control alongside antimicrobials and resuscitation',[
 ('Antibiotics alone are always sufficient despite persistent obstruction','An uncontrolled anatomical source can prevent recovery.'),('Defer drainage until all vasopressors have been stopped','Source control often cannot wait for complete stabilization.'),('Treat only the lactate value without addressing the obstruction','Physiological support does not eliminate the infected source.')],
 'Antimicrobials cannot substitute for every anatomical intervention', '**Drainage, debridement or removal may be necessary for definitive control.**',['Choose the least invasive effective method where appropriate.','Coordinate the procedural team early.'], '**Resuscitate and arrange source control in parallel.**',['SSC 2026 favors early control, ideally within six hours when required.','The safest feasible timing depends on the specific emergency and procedure.'],[['Antibiotics','Treat susceptible organisms'],['Source control','Remove the ongoing anatomical driver'],['Timing','Early, with simultaneous support']],[SS],style='clinical_scenario')
q('Which lactate interpretation is most accurate in sepsis?', 'An elevated value indicates increased risk but can reflect several production and clearance mechanisms',[
 ('Every elevation proves ongoing volume depletion','Adrenergic metabolism and impaired clearance can contribute.'),('A normal value excludes sepsis','Sepsis can occur without hyperlactatemia.'),('Give fluid until lactate is normal regardless of congestion','This can cause harmful over-resuscitation.')],
 'Lactate is a risk and response marker with mechanistic limitations', '**Interpret trends with blood pressure, skin perfusion and organ function.**',['Liver dysfunction can impair clearance.','Catecholamines can increase lactate without a simple one-to-one relation to hypoxia.'], '**Investigate persistent elevation rather than reflexively giving more fluid.**',['Assess fluid responsiveness and tolerance.','Treat the underlying source and circulatory problem.'],[['Elevated lactate','Risk signal with several mechanisms'],['Trend','Useful with other perfusion measures'],['Fluid decision','Not based on lactate alone']],[SS,S3])

if __name__=='__main__':print('Sepsis recognition: '+str(len(rows))+' questions drafted')
